lue="warning">Aviso</option><option value="danger">Error</option></select></label></div><label class="grid gap-1 text-xs"><span>Reintentos</span><select class="kt-select" id="xflow_node_retries"><option value="0">Sin reintentos</option><option value="1">1 reintento</option><option value="2">2 reintentos</option></select></label><div class="border-t border-input pt-3"><div class="mb-2 text-xs font-medium text-mono">Conexiones salientes</div><div class="grid gap-2" id="xflow_edge_list"></div></div></div>
