<script>
document.addEventListener('DOMContentLoaded',()=>{
 const catalog=@json($catalog),nodesRoot=document.getElementById('xflow_nodes'),canvas=document.getElementById('xflow_canvas'),svg=document.getElementById('xflow_lines');
 let nodes=@json($workflow->nodes??[]),edges=@json($workflow->edges??[]),selected=null,connecting=null,drag=null,seq=Date.now();
 const byId=id=>nodes.find(n=>n.id===id),def=n=>catalog[n.handler]||{},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function render(){nodesRoot.innerHTML=nodes.map(n=>`<div class="xflow-node ${selected===n.id?'selected':''} ${connecting===n.id?'connecting':''}" tabindex="0" data-node="${esc(n.id)}" style="left:${n.x}px;top:${n.y}px"><button class="xflow-port in" type="button" data-input="${esc(n.id)}" aria-label="Conectar a ${esc(n.label)}"></button><div class="xflow-node-head"><span class="flex size-8 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><i class="ki-filled ${esc(def(n).icon||'ki-abstract-26')}"></i></span><span class="min-w-0"><span class="block truncate text-xs font-semibold text-mono">${esc(n.label)}</span><span class="block truncate text-[10px] text-secondary-foreground">${esc(def(n).label||n.handler)}</span></span></div><div class="xflow-node-body">${n.type==='condition'?'Salidas verdadero / falso':n.type==='trigger'?'Punto inicial':'Acción segura de XPanel'}</div><button class="xflow-port out" type="button" data-output="${esc(n.id)}" aria-label="Conectar desde ${esc(n.label)}"></button></div>`).join('');renderLines();renderInspector();sync();}
 function renderLines(){svg.innerHTML=edges.map(e=>{const a=byId(e.from),b=byId(e.to);if(!a||!b)return'';const x1=a.x+190,y1=a.y+43,x2=b.x,y2=b.y+43,m=(x1+x2)/2;return`<path class="xflow-line" d="M ${x1} ${y1} C ${m} ${y1}, ${m} ${y2}, ${x2} ${y2}"/><text x="${m}" y="${(y1+y2)/2-5}" fill="currentColor" font-size="10">${esc(e.branch)}</text>`}).join('')}
 function add(handler){const d=catalog[handler];if(!d)return;const id='node-'+(++seq),offset=nodes.length*25;nodes.push({id,type:d.type,handler,label:d.label,x:360+offset%700,y:120+offset%500,config:{target:'workflow',site_id:null,operator:'equals',value:'',retries:0}});selected=id;render()}
 function select(id){if(connecting&&connecting!==id){if(!edges.some(e=>e.from===connecting&&e.to===id))edges.push({from:connecting,to:id,branch:'always'});connecting=null;selected=id;render();return}selected=id;render()}
 function renderInspector(){const n=byId(selected),empty=document.getElementById('xflow_empty_inspector'),panel=document.getElementById('xflow_node_inspector');empty.classList.toggle('hidden',!!n);panel.classList.toggle('hidden',!n);if(!n)return;document.getElementById('xflow_node_type').textContent=def(n).label||n.handler;document.getElementById('xflow_node_label').value=n.label;const target=document.getElementById('xflow_node_target');target.value=n.config?.target||'workflow';document.getElementById('xflow_node_site').value=n.config?.site_id||'';document.getElementById('xflow_node_site_field').classList.toggle('hidden',target.value!=='site');document.getElementById('xflow_target_fields').classList.toggle('hidden',n.type==='trigger'||n.handler==='action.notify');document.getElementById('xflow_condition_fields').classList.toggle('hidden',n.type!=='condition');document.getElementById('xflow_node_operator').value=n.config?.operator||'equals';document.getElementById('xflow_node_value').value=n.config?.value||'';document.getElementById('xflow_notify_fields').classList.toggle('hidden',n.handler!=='action.notify');document.getElementById('xflow_notify_title').value=n.config?.title||'';document.getElementById('xflow_notify_message').value=n.config?.message||'';document.getElementById('xflow_notify_level').value=n.config?.level||'info';document.getElementById('xflow_node_retries').value=n.config?.retries||0;document.getElementById('xflow_delete_node').classList.toggle('hidden',n.type==='trigger');document.getElementById('xflow_edge_list').innerHTML=edges.filter(e=>e.from===n.id).map((e,i)=>`<div class="flex items-center gap-2"><span class="min-w-0 grow truncate text-xs">→ ${esc(byId(e.to)?.label||e.to)}</span><select class="kt-select h-8 w-24 text-xs" data-edge-branch="${esc(e.from)}|${esc(e.to)}"><option value="always" ${e.branch==='always'?'selected':''}>Siempre</option><option value="success" ${e.branch==='success'?'selected':''}>Éxito</option><option value="failure" ${e.branch==='failure'?'selected':''}>Fallo</option><option value="true" ${e.branch==='true'?'selected':''}>Verdadero</option><option value="false" ${e.branch==='false'?'selected':''}>Falso</option></select><button class="kt-btn kt-btn-sm kt-btn-icon kt-btn-ghost" type="button" data-edge-delete="${esc(e.from)}|${esc(e.to)}"><i class="ki-filled ki-cross"></i></button></div>`).join('')||'<span class="text-xs text-secondary-foreground">Sin conexiones.</span>'}
 function updateConfig(key,value){const n=byId(selected);if(!n)return;n.config=n.config||{};n.config[key]=value;sync()}
 function sync(){document.getElementById('xflow_nodes_json').value=JSON.stringify(nodes);document.getElementById('xflow_edges_json').value=JSON.stringify(edges)}
 document.querySelectorAll('[data-add-node]').forEach(b=>b.addEventListener('click',()=>add(b.dataset.addNode)));
 nodesRoot.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-node]');if(!card||e.target.closest('.xflow-port'))return;select(card.dataset.node);const n=byId(card.dataset.node),rect=canvas.getBoundingClientRect();drag={id:n.id,dx:e.clientX-rect.left-n.x,dy:e.clientY-rect.top-n.y};card.setPointerCapture(e.pointerId)});
 nodesRoot.addEventListener('pointermove',e=>{if(!drag)return;const n=byId(drag.id),rect=canvas.getBoundingClientRect();n.x=Math.max(10,Math.min(1590,e.clientX-rect.left-drag.dx));n.y=Math.max(10,Math.min(990,e.clientY-rect.top-drag.dy));const card=nodesRoot.querySelector(`[data-node="${CSS.escape(n.id)}"]`);card.style.left=n.x+'px';card.style.top=n.y+'px';renderLines();sync()});
 nodesRoot.addEventListener('pointerup',()=>drag=null);nodesRoot.addEventListener('click',e=>{const out=e.target.closest('[data-output]'),input=e.target.closest('[data-input]'),card=e.target.closest('[data-node]');if(out){e.stopPropagation();connecting=out.dataset.output;selected=connecting;render()}else if(input){e.stopPropagation();select(input.dataset.input)}else if(card&&!drag)select(card.dataset.node)});
 nodesRoot.addEventListener('keydown',e=>{const card=e.target.closest('[data-node]');if(!card)return;const n=byId(card.dataset.node);if(!n)return;if(e.key==='Enter'){e.preventDefault();select(n.id);return}const movement={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]}[e.key];if(movement){e.preventDefault();n.x=Math.max(10,Math.min(1590,n.x+movement[0]));n.y=Math.max(10,Math.min(990,n.y+movement[1]));render();nodesRoot.querySelector(`[data-node="${CSS.escape(n.id)}"]`)?.focus()}});
 document.getElementById('xflow_node_label').addEventListener('input',e=>{const n=byId(selected);if(!n)return;n.label=e.target.value;const label=nodesRoot.querySelector(`[data-node="${CSS.escape(n.id)}"] .xflow-node-head .font-semibold`);if(label)label.textContent=n.label;sync()});document.getElementById('xflow_node_target').addEventListener('change',e=>{updateConfig('target',e.target.value);renderInspector()});document.getElementById('xflow_node_site').addEventListener('change',e=>updateConfig('site_id',Number(e.target.value)||null));document.getElementById('xflow_node_operator').addEventListener('change',e=>updateConfig('operator',e.target.value));document.getElementById('xflow_node_value').addEventListener('input',e=>updateConfig('value',e.target.value));document.getElementById('xflow_notify_title').addEventListener('input',e=>updateConfig('title',e.target.value));document.getElementById('xflow_notify_message').addEventListener('input',e=>updateConfig('message',e.target.value));document.getElementById('xflow_notify_level').addEventListener('change',e=>updateConfig('level',e.target.value));document.getElementById('xflow_node_retries').addEventListener('change',e=>updateConfig('retries',Number(e.target.value)));
 document.getElementById('xflow_delete_node').addEventListener('click',()=>{const n=byId(selected);if(!n||n.type==='trigger')return;nodes=nodes.filter(x=>x.id!==selected);edges=edges.filter(e=>e.from!==selected&&e.to!==selected);selected=null;render()});document.getElementById('xflow_edge_list').addEventListener('change',e=>{if(!e.target.dataset.edgeBranch)return;const [from,to]=e.target.dataset.edgeBranch.split('|'),edge=edges.find(x=>x.from===from&&x.to===to);if(edge){edge.branch=e.target.value;sync();renderLines()}});document.getElementById('xflow_edge_list').addEventListener('click',e=>{const b=e.target.closest('[data-edge-delete]');if(!b)return;const[from,to]=b.dataset.edgeDelete.split('|');edges=edges.filter(x=>!(x.from===from&&x.to===to));render()});document.querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>document.querySelector('.xflow-'+b.dataset.toggle).classList.toggle('is-collapsed')));document.getElementById('xflow_builder_form').addEventListener('submit',sync);render();
});
</script>
@endsection
